import React, {Component} from 'react';
import './App.css';

function BookClass(){
    return(
        <div className="App">
            <header className="App-header">
                <table border={2}>
                    <tr>
                        <th>Sunday</th>
                        <td>AAD</td>
                        <td>WAF</td>
                    </tr>
                </table>

            </header>
        </div>
    );
}
export default BookClass;
